package com.careerconnect.jobportal.config;
import com.careerconnect.jobportal.model.*; import com.careerconnect.jobportal.repository.*; import java.math.BigDecimal; import java.time.LocalDate; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer {
 @Bean CommandLineRunner seed(PortalUserRepository users,JobRepository jobs,PasswordEncoder encoder){return args->{if(!users.existsByUsername("admin")){PortalUser a=new PortalUser();a.setUsername("admin");a.setPassword(encoder.encode("admin123"));a.setFullName("CareerConnect Admin");a.setEmail("admin@careerconnect.com");a.setRole(com.careerconnect.jobportal.model.Role.ADMIN);users.save(a);}if(jobs.count()==0){add(jobs,"Python Developer","Tech Solutions Pvt. Ltd.","Bengaluru","Information Technology",35000);add(jobs,"Data Analyst","Insight Analytics Pvt. Ltd.","Hyderabad","Information Technology",40000);add(jobs,"HR Recruiter","TalentBridge Solutions","Mumbai","Human Resources",28000);}};}
 private void add(JobRepository r,String title,String company,String location,String category,int salary){Job j=new Job();j.setTitle(title);j.setCompanyName(company);j.setLocation(location);j.setCategory(category);j.setDescription("We are looking for a motivated candidate with relevant basic knowledge and good communication skills. Freshers may apply.");j.setSalary(BigDecimal.valueOf(salary));j.setDeadline(LocalDate.now().plusMonths(4));r.save(j);}
}
